const email = $json               //$json.payload?.headers?.find(h => h.name === "From")?.value || "";
const subject = $json.payload?.headers?.find(h => h.name === "Subject")?.value || "";
const snippet = $json.snippet || $json.body || "";

return [{
  json: {
    email,
    subject,
    reviewSnippet: snippet,
    receivedDate: new Date().toISOString()
  }
}];

