const jsonData = typeof $json === 'object' && $json !== null ? $json : {};
const binaryData = typeof $binary === 'object' && $binary !== null ? $binary : {};

const snippet = jsonData.snippet?.toLowerCase() || '';
const mentionsVoicemail = snippet.includes("voicemail");

const hasAudioAttachment = binaryData.attachment_0?.mimeType?.includes("audio");

const voicemailDetected = hasAudioAttachment || mentionsVoicemail;

return [
  {
    json: {
      ...jsonData,
      voicemailDetected
    },
    binary: binaryData
  }
];
